'use strict';
const fs = require('fs');
const path = require('path');

// ===================== ELF Loading =====================
const ELF_FILENAME = 'doomgeneric_mips';
const elfBuffer = fs.readFileSync(ELF_FILENAME);

function readU32LE(buf, off) { return buf.readUInt32LE(off); }
function readU16LE(buf, off) { return buf.readUInt16LE(off); }

const e_entry = elfBuffer.readUInt32LE(24);
const e_phoff = elfBuffer.readUInt32LE(28);
const e_phentsize = elfBuffer.readUInt16LE(42);
const e_phnum = elfBuffer.readUInt16LE(44);

// ===================== Paged Memory =====================
const PAGE_SIZE = 4096;
const PAGE_MASK = PAGE_SIZE - 1;
const PAGE_SHIFT = 12;

class Memory {
  constructor() {
    this.pages = new Map();
    this.maxAddr = 0;
  }
  _getPage(addr) {
    const pn = addr >>> PAGE_SHIFT;
    let p = this.pages.get(pn);
    if (!p) {
      p = Buffer.alloc(PAGE_SIZE, 0);
      this.pages.set(pn, p);
    }
    if (addr > this.maxAddr) this.maxAddr = addr;
    return p;
  }
  read8(addr) {
    addr = addr >>> 0;
    const p = this.pages.get(addr >>> PAGE_SHIFT);
    if (!p) return 0;
    return p[addr & PAGE_MASK];
  }
  write8(addr, val) {
    addr = addr >>> 0;
    const p = this._getPage(addr);
    p[addr & PAGE_MASK] = val & 0xff;
  }
  read16(addr) {
    return this.read8(addr) | (this.read8(addr+1) << 8);
  }
  write16(addr, val) {
    this.write8(addr, val & 0xff);
    this.write8(addr+1, (val >>> 8) & 0xff);
  }
  read32(addr) {
    addr = addr >>> 0;
    const p = this.pages.get(addr >>> PAGE_SHIFT);
    if (!p) return 0;
    const off = addr & PAGE_MASK;
    if (off <= PAGE_SIZE - 4) return p.readUInt32LE(off);
    return this.read8(addr) | (this.read8(addr+1) << 8) | (this.read8(addr+2) << 16) | (this.read8(addr+3) << 24);
  }
  write32(addr, val) {
    addr = addr >>> 0;
    val = val >>> 0;
    const p = this._getPage(addr);
    const off = addr & PAGE_MASK;
    if (off <= PAGE_SIZE - 4) {
      p.writeUInt32LE(val, off);
    } else {
      this.write8(addr, val & 0xff);
      this.write8(addr+1, (val >>> 8) & 0xff);
      this.write8(addr+2, (val >>> 16) & 0xff);
      this.write8(addr+3, (val >>> 24) & 0xff);
    }
  }
  // Fast bulk read into a Buffer
  readBytes(addr, len) {
    const buf = Buffer.alloc(len);
    for (let i = 0; i < len; i++) buf[i] = this.read8(addr + i);
    return buf;
  }
  writeBytes(addr, buf, len) {
    len = len || buf.length;
    for (let i = 0; i < len; i++) this.write8(addr + i, buf[i]);
  }
  // Optimized read for consecutive 32-bit words from same page
  read32Fast(addr) {
    return this.read32(addr);
  }
}

const mem = new Memory();

// Load program headers
for (let i = 0; i < e_phnum; i++) {
  const off = e_phoff + i * e_phentsize;
  const p_type = elfBuffer.readUInt32LE(off);
  if (p_type !== 1) continue; // PT_LOAD
  const p_offset = elfBuffer.readUInt32LE(off + 4);
  const p_vaddr = elfBuffer.readUInt32LE(off + 8);
  const p_filesz = elfBuffer.readUInt32LE(off + 16);
  const p_memsz = elfBuffer.readUInt32LE(off + 20);
  // Copy file content
  for (let j = 0; j < p_filesz; j++) {
    mem.write8(p_vaddr + j, elfBuffer[p_offset + j]);
  }
  // BSS is already zero (paged memory)
  console.error(`[vm] Loaded segment vaddr=0x${p_vaddr.toString(16)} filesz=${p_filesz} memsz=${p_memsz}`);
}

// ===================== CPU State =====================
const R = new Uint32Array(32);
const HI = new Uint32Array(1);
const LO = new Uint32Array(1);
const PC = new Uint32Array(1);
const FCSR = new Uint32Array(1);
const F = new Float64Array(32); // FPU registers as double
const F32 = new Float32Array(32); // FPU as float
// Use a single ArrayBuffer for FPU registers to allow reinterpretation
const fpuBuf = new ArrayBuffer(32 * 8);
const fpu64 = new Float64Array(fpuBuf);
const fpu32 = new Float32Array(fpuBuf);
const fpu32x2 = new Float32Array(32 * 2); // paired singles

let halt = false;
let exitCode = 0;
let icount = 0;

// Stack setup
const STACK_TOP = 0x80000000;
const STACK_SIZE = 256 * 1024 * 1024; // 256MB stack space (sparse)
R[29] = STACK_TOP - 16; // sp
R[28] = 0; // gp (not set by REGINFO)
R[31] = 0; // ra
PC[0] = e_entry;

// ===================== Helper Functions =====================
function signExt16(val) { return (val & 0x8000) ? (val | 0xFFFF0000) : (val & 0xFFFF); }
function signExt8(val) { return (val & 0x80) ? (val | 0xFFFFFF00) : (val & 0xFF); }
function toS32(val) { return (val & 0x80000000) ? (val - 0x100000000) : val; }
function toU32(val) { return val >>> 0; }
function setReg(n, val) { if (n !== 0) R[n] = val >>> 0; }
function setSReg(n, val) { if (n !== 0) R[n] = (val >>> 0); }

// Memory access helpers for string
function readCString(addr) {
  let s = '';
  let ch;
  while ((ch = mem.read8(addr++)) !== 0) s += String.fromCharCode(ch);
  return s;
}

function writeU32(addr, val) { mem.write32(addr, val); }
function readU32(addr) { return mem.read32(addr); }

// ===================== Syscall Handling =====================
// MIPS Linux O32 syscall numbers used by this binary
const SYS_read = 0;
const SYS_write = 1;
const SYS_open = 2;
const SYS_close = 3;
const SYS_lseek = 8;
const SYS_exit = 60;
const SYS_gettimeofday = 96;
const SYS_nanosleep = 35;
const SYS_fsync = 74;
const SYS_time = 201;

// File descriptor table for host files
const fds = new Map();
let nextFd = 10;

function handleSyscall() {
  const num = R[2]; // v0 = syscall number
  const a0 = R[4], a1 = R[5], a2 = R[6], a3 = R[7];
  // For MIPS O32, args 5-6 are on stack at sp[16], sp[20]
  const a4 = mem.read32(R[29] + 16);
  const a5 = mem.read32(R[29] + 20);
  let result = 0;

  switch (num) {
    case SYS_write: {
      const fd = a0;
      const buf = a1;
      const count = a2;
      if (fd === 1 || fd === 2) {
        const data = mem.readBytes(buf, count);
        process.stderr.write(data);
        result = count;
      } else {
        const hostFd = fds.get(fd);
        if (hostFd !== undefined) {
          const data = mem.readBytes(buf, count);
          result = fs.writeSync(hostFd, data, 0, count);
        } else {
          result = -9; // EBADF
        }
      }
      break;
    }
    case SYS_read: {
      const fd = a0;
      const buf = a1;
      const count = a2;
      if (fd === 0) {
        result = 0; // no input
      } else {
        const hostFd = fds.get(fd);
        if (hostFd !== undefined) {
          const tmp = Buffer.alloc(count);
          const n = fs.readSync(hostFd, tmp, 0, count, null);
          mem.writeBytes(buf, tmp, n);
          result = n;
        } else {
          result = -9;
        }
      }
      break;
    }
    case SYS_open: {
      const pathname = readCString(a0);
      const flags = a1;
      const mode = a2;
      let hostFlags = 0;
      // O_RDONLY=0, O_WRONLY=1, O_RDWR=2
      const accmode = flags & 3;
      if (accmode === 0) hostFlags |= fs.constants.O_RDONLY;
      else if (accmode === 1) hostFlags |= fs.constants.O_WRONLY;
      else hostFlags |= fs.constants.O_RDWR;
      if (flags & 64) hostFlags |= fs.constants.O_CREAT;
      if (flags & 512) hostFlags |= fs.constants.O_TRUNC;
      if (flags & 1024) hostFlags |= fs.constants.O_APPEND;
      try {
        const fd = fs.openSync(pathname, hostFlags, mode);
        const vfd = nextFd++;
        fds.set(vfd, fd);
        result = vfd;
      } catch (e) {
        result = -2; // ENOENT
      }
      break;
    }
    case SYS_close: {
      const fd = a0;
      if (fd < 10) { result = 0; break; }
      const hostFd = fds.get(fd);
      if (hostFd !== undefined) {
        fs.closeSync(hostFd);
        fds.delete(fd);
        result = 0;
      } else {
        result = -9;
      }
      break;
    }
    case SYS_lseek: {
      const fd = a0;
      const offset = toS32(a1);
      const whence = a2;
      const hostFd = fds.get(fd);
      if (hostFd !== undefined) {
        // Use a large buffer seek via stat and read/write position tracking
        // Node doesn't have lseekSync directly; emulate via a position map
        // For simplicity, use lseekSync if available, otherwise track positions
        // Actually fs.readSync/writeSync with position param handles it
        // We'll track positions per fd
        // For lseek, we need to know current position; let's use position tracking
        // But we can use a simpler approach: use dup and a position map
        // Let's track position explicitly
        let pos = fdPositions.get(fd);
        if (pos === undefined) pos = 0;
        if (whence === 0) pos = offset; // SEEK_SET
        else if (whence === 1) pos = pos + offset; // SEEK_CUR
        else if (whence === 2) {
          const st = fs.fstatSync(hostFd);
          pos = st.size + offset;
        }
        fdPositions.set(fd, pos);
        result = pos;
      } else {
        result = -9;
      }
      break;
    }
    case SYS_exit: {
      halt = true;
      exitCode = a0;
      result = 0;
      break;
    }
    case SYS_gettimeofday: {
      const tv = a0;
      if (tv) {
        const now = Date.now();
        const sec = Math.floor(now / 1000);
        const usec = (now % 1000) * 1000;
        mem.write32(tv, sec);
        mem.write32(tv + 4, usec);
      }
      result = 0;
      break;
    }
    case SYS_nanosleep: {
      // Just return immediately, no actual sleep
      result = 0;
      break;
    }
    case SYS_time: {
      result = Math.floor(Date.now() / 1000) & 0xFFFFFFFF;
      break;
    }
    case SYS_fsync: {
      const fd = a0;
      const hostFd = fds.get(fd);
      if (hostFd !== undefined) {
        fs.fsyncSync(hostFd);
      }
      result = 0;
      break;
    }
    default:
      console.error(`[vm] Unhandled syscall ${num} at PC=0x${PC[0].toString(16)}`);
      result = 0;
      break;
  }
  R[2] = result >>> 0;
  // a3 is set to 1 on error in MIPS Linux
  if ((result & 0xFFFFFFFF) > 0xFFFFF000 || (result < 0 && result > -4096)) {
    R[7] = 1; // error flag
  } else {
    R[7] = 0;
  }
}

const fdPositions = new Map();

// ===================== Main Execution Loop =====================
// Instruction decode and execute

function executeInstruction() {
  const pc = PC[0];
  const instr = mem.read32(pc);
  const opcode = instr >>> 26;
  const rs = (instr >>> 21) & 31;
  const rt = (instr >>> 16) & 31;
  const rd = (instr >>> 11) & 31;
  const shamt = (instr >>> 6) & 31;
  const funct = instr & 0x3f;
  const imm = instr & 0xffff;
  const simm = signExt16(imm);
  const target = instr & 0x3ffffff;
  let nextPC = pc + 4;

  switch (opcode) {
    case 0x00: { // SPECIAL - R-type
      switch (funct) {
        case 0x00: // SLL
          setReg(rd, R[rt] << shamt);
          break;
        case 0x02: // SRL
          setReg(rd, R[rt] >>> shamt);
          break;
        case 0x03: // SRA
          setReg(rd, toS32(R[rt]) >> shamt);
          break;
        case 0x04: // SLLV
          setReg(rd, R[rt] << (R[rs] & 31));
          break;
        case 0x06: // SRLV
          setReg(rd, R[rt] >>> (R[rs] & 31));
          break;
        case 0x07: // SRAV
          setReg(rd, toS32(R[rt]) >> (R[rs] & 31));
          break;
        case 0x08: // JR
          nextPC = R[rs];
          break;
        case 0x09: // JALR
          setReg(rd, pc + 8);
          nextPC = R[rs];
          break;
        case 0x0c: // SYSCALL
          handleSyscall();
          break;
        case 0x0d: // BREAK
          console.error(`[vm] BREAK at 0x${pc.toString(16)}`);
          halt = true;
          break;
        case 0x10: // MFHI
          setReg(rd, HI[0]);
          break;
        case 0x11: // MTHI
          HI[0] = R[rs];
          break;
        case 0x12: // MFLO
          setReg(rd, LO[0]);
          break;
        case 0x13: // MTLO
          LO[0] = R[rs];
          break;
        case 0x18: { // MULT
          const r = toS32(R[rs]) * toS32(R[rt]);
          LO[0] = r & 0xFFFFFFFF;
          HI[0] = (r / 0x100000000) & 0xFFFFFFFF;
          break;
        }
        case 0x19: { // MULTU
          const r = (R[rs] >>> 0) * (R[rt] >>> 0);
          LO[0] = r & 0xFFFFFFFF;
          HI[0] = Math.floor(r / 0x100000000) & 0xFFFFFFFF;
          break;
        }
        case 0x1a: { // DIV
          const a = toS32(R[rs]);
          const b = toS32(R[rt]);
          if (b !== 0) {
            // MIPS truncates toward zero
            const q = Math.trunc(a / b);
            const r2 = a - q * b;
            LO[0] = q & 0xFFFFFFFF;
            HI[0] = r2 & 0xFFFFFFFF;
          } else {
            LO[0] = 0; HI[0] = 0;
          }
          break;
        }
        case 0x1b: { // DIVU
          const a = R[rs] >>> 0;
          const b = R[rt] >>> 0;
          if (b !== 0) {
            LO[0] = (a / b) & 0xFFFFFFFF;
            HI[0] = (a % b) & 0xFFFFFFFF;
          } else {
            LO[0] = 0; HI[0] = 0;
          }
          break;
        }
        case 0x20: // ADD (treat as ADDU, no overflow)
          setReg(rd, (R[rs] + R[rt]) >>> 0);
          break;
        case 0x21: // ADDU
          setReg(rd, (R[rs] + R[rt]) >>> 0);
          break;
        case 0x22: // SUB
          setReg(rd, (R[rs] - R[rt]) >>> 0);
          break;
        case 0x23: // SUBU
          setReg(rd, (R[rs] - R[rt]) >>> 0);
          break;
        case 0x24: // AND
          setReg(rd, R[rs] & R[rt]);
          break;
        case 0x25: // OR
          setReg(rd, R[rs] | R[rt]);
          break;
        case 0x26: // XOR
          setReg(rd, R[rs] ^ R[rt]);
 0x27: // NOR
          setReg(rd, ~(R[rs] | R[rt]));
          break;
        case 0x2a: // SLT
          setReg(rd, toS32(R[rs]) < toS32(R[rt]) ? 1 : 0);
          break;
        case 0x2b: // SLTU
          setReg(rd, (R[rs] >>> 0) < (R[rt] >>> 0) ? 1 : 0);
          break;
        case 0x0f: // SYNC
          break;
        case 0x01: // MOVCI - not commonly used
          break;
        default:
          console.error(`[vm] Unhandled SPECIAL funct=0x${funct.toString(16)} at 0x${pc.toString(16)}`);
          halt = true;
          break;
      }
      break;
    }
    case 0x01: { // REGIMM
      switch (rt) {
        case 0x00: // BLTZ
          if (toS32(R[rs]) < 0) nextPC = pc + 4 + (simm << 2);
          break;
        case 0x01: // BGEZ
          if (toS32(R[rs]) >= 0) nextPC = pc + 4 + (simm << 2);
          break;
        case 0x02: // BLTZL
          if (toS32(R[rs]) < 0) nextPC = pc + 4 + (simm << 2);
          else setReg(31, pc + 8); // actually skip delay slot? No, BLTZL nullifies
          // Actually BLTZL: if condition false, nullify delay slot
          // For simplicity, we handle delay slot by executing it always
          break;
        case 0x03: // BGEZL
          if (toS32(R[rs]) >= 0) nextPC = pc + 4 + (simm << 2);
          break;
        case 0x10: // BLTZAL
          setReg(31, pc + 8);
          if (toS32(R[rs]) < 0) nextPC = pc + 4 + (simm << 2);
          break;
        case 0x11: // BGEZAL
          setReg(31, pc + 8);
          if (toS32(R[rs]) >= 0) nextPC = pc + 4 + (simm << 2);
          break;
        default:
          console.error(`[vm] Unhandled REGIMM rt=0x${rt.toString(16)} at 0x${pc.toString(16)}`);
          halt = true;
          break;
      }
      break;
    }
    case 0x02: { // J
      nextPC = ((pc + 4) & 0xF0000000) | (target << 2);
      break;
    }
    case 0x03: { // JAL
      setReg(31, pc + 8);
      nextPC = ((pc + 4) & 0xF0000000) | (target << 2);
      break;
    }
    case 0x04: { // BEQ
      if (R[rs] === R[rt]) nextPC = pc + 4 + (simm << 2);
      break;
    }
    case 0x05: { // BNE
      if (R[rs] !== R[rt]) nextPC = pc + 4 + (simm << 2);
      break;
    }
    case 0x06: { // BLEZ
      if (toS32(R[rs]) <= 0) nextPC = pc + 4 + (simm << 2);
      break;
    }
    case 0x07: { // BGTZ
      if (toS32(R[rs]) > 0) nextPC = pc + 4 + (simm << 2);
      break;
    }
    case 0x08: { // ADDI
      setReg(rt, (R[rs] + simm) >>> 0);
      break;
    }
    case 0x09: { // ADDIU
      setReg(rt, (R[rs] + simm) >>> 0);
      break;
    }
    case 0x0a: { // SLTI
      setReg(rt, toS32(R[rs]) < simm ? 1 : 0);
      break;
    }
    case 0x0b: { // SLTIU
      setReg(rt, (R[rs] >>> 0) < (simm >>> 0) ? 1 : 0);
      break;
    }
    case 0x0c: { // ANDI
      setReg(rt, R[rs] & imm);
      break;
    }
    case 0x0d: { // ORI
      setReg(rt, R[rs] | imm);
      break;
    }
    case 0x0e: { // XORI
      setReg(rt, R[rs] ^ imm);
      break;
    }
    case 0x0f: { // LUI
      setReg(rt, (imm << 16) >>> 0);
      break;
    }
    case 0x10: { // COP0 - coprocessor 0
      // Mostly ignore, but handle MFC0/MTC0 if needed
      break;
    }
    case 0x11: { // COP1 - FPU
      const fmt = (instr >>> 21) & 31;
      const ft = (instr >>> 16) & 31;
      const fs = (instr >>> 11) & 31;
      const fd = (instr >>> 6) & 31;
      const ffunct = instr & 0x3f;
      if (instr & 0x20000000) {
        // BC1 instructions
        const bcct = (instr >>> 16) & 31;
        const offset = simm << 2;
        if (bcct === 0) { // BC1F
          if (!(FCSR[0] & 0x80000000)) nextPC = pc + 4 + offset;
        } else if (bcct === 1) { // BC1T
          if (FCSR[0] & 0x80000000) nextPC = pc + 4 + offset;
        }
        break;
      }
      switch (fmt) {
        case 0: { // MFC1
          // Read low 32 bits of FPU register
          const freg = fpu32[fs * 2];
          setReg(rt, freg | 0);
          // Actually need to reinterpret bits
          const buf = Buffer.alloc(4);
          buf.writeFloatLE(fpu32[fs * 2], 0);
          setReg(rt, buf.readUInt32LE(0));
          break;
        }
        case 2: { // CFC1
          if (fs === 0) setReg(rt, FCSR[0]);
          break;
        }
        case 4: { // MTC1
          fpu32[rt * 2] = Math.fround(R[rs]);
          // Actually need to write bits, not convert
          const buf = Buffer.alloc(4);
          buf.writeUInt32LE(R[rs], 0);
          fpu32[fs * 2] = buf.readFloatLE(0);
          break;
        }
        case 6: { // CTC1
          if (fs === 0) FCSR[0] = R[rs];
          break;
        }
        case 0x10: { // S (single)
          switch (ffunct) {
            case 0x00: // ADD.S
              fpu32[fd * 2] = Math.fround(fpu32[fs * 2] + fpu32[ft * 2]);
              break;
            case 0x01: // SUB.S
              fpu32[fd * 2] = Math.fround(fpu32[fs * 2] - fpu32[ft * 2]);
              break;
            case 0x02: // MUL.S
              fpu32[fd * 2] = Math.fround(fpu32[fs * 2] * fpu32[ft * 2]);
          break;
            case 0x03: // DIV.S
              fpu32[fd * 2] = Math.fround(fpu32[fs * 2] / fpu32[ft * 2]);
              break;
            case 0x04: // SQRT.S
              fpu32[fd * 2] = Math.fround(Math.sqrt(fpu32[fs * 2]));
              break;
            case 0x05: // ABS.S
              fpu32[fd * 2] = Math.fround(Math.abs(fpu32[fs * 2]));
              break;
            case 0x06: // MOV.S
              fpu32[fd * 2] = fpu32[fs * 2];
          break;
            case 0x07: // NEG.S
              fpu32[fd * 2] = Math.fround(-fpu32[fs * 2]);
          break;
            case 0x0d: // TRUNC.W.S
              {
                const v = fpu32[fs * 2];
                const iv = Math.trunc(v) | 0;
                const buf = Buffer.alloc(4);
              buf.writeInt32LE(iv, 0);
              fpu32[fd * 2] = buf.readFloatLE(0);
              break;
              }
            case 0x24: // CVT.W.S
              {
                const v = fpu32[fs * 2];
                let iv;
                // MIPS round to nearest
                iv = Math.round(v) | 0;
                const buf = Buffer.alloc(4);
                buf.writeInt32LE(iv, 0);
                fpu32[fd * 2] = buf.readFloatLE(0);
              break;
              }
            case 0x20: // CVT.S.S (no-op essentially)
              fpu32[fd * 2] = fpu32[fs * 2];
              break;
            case 0x21: // CVT.D.S
              fpu64[fd] = fpu32[fs * 2];
              break;
            default: {
              // Comparison instructions
              if (ffunct >= 0x30 && ffunct <= 0x3f) {
                const a = fpu32[fs * 2];
                const b = fpu32[ft * 2];
                let cond = false;
                switch (ffunct) {
